// Safe in-memory storage wrapper — artifact environment has no localStorage
const safeStorage = (() => {
  const mem = {};
  return {
    getItem: (k) => mem[k] !== undefined ? mem[k] : null,
    setItem: (k, v) => { mem[k] = String(v); },
    removeItem: (k) => { delete mem[k]; }
  };
})();

