const getWallAssemblyBuilderCompleted = (selections) => {
  let count = 0;
  ['wabExteriorCladding', 'wabExteriorTrim', 'wabDrywallScope', 'wabPaintQuality'].forEach(id => { if (selections[id]) count++; });
  const scope = selections.wabDrywallScope;
  if (scope === 'keepExisting' || scope === 'partialRework') { if (selections.wabInteriorFinish) count++; }
  else if (scope === 'fullReplacement') { if (selections.wabInsulationType && selections.wabAcousticStrategy && selections.wabFinishLevel) count++; }
  return count;
};

