const bathroomKnowledgeTopicIds = ['tubType', 'showerType', 'toilet', 'faucet', 'vanityType', 'tileTrim', 'niche'];
const bathroomKnowledgeDecisions = bathroomKnowledgeTopicIds.reduce((acc, id) => {
  const d = decisions[id];
  if (!d) return acc;
  // Tub Type: exclude "No tub" option for Knowledge view (Knowledge is educational comparison only)
  if (id === 'tubType') {
    acc[id] = { ...d, options: d.options.filter(o => o.value !== 'none') };
  } else {
    acc[id] = d;
  }
  return acc;
}, {});

// Kitchen completion checker — handles compound decisions (island sub-options, electrical sub-sections)
const getKitchenMandatoryCompleted = (selections) => {
  let count = 0;
  ['kitchenLayoutChange', 'kitchenOpenClosed', 'kitchenSink', 'kitchenCooking', 'kitchenVentilation', 'kitchenCabinet'].forEach(id => {
    if (selections[id]) count++;
  });
  // Island: complete if 'none' or (add/modify WITH utilities selected)
  if (selections.kitchenIsland) {
    if (selections.kitchenIsland === 'none') count++;
    else if (selections.kitchenIslandUtilities) count++;
  }
  // Electrical: complete if BOTH sub-sections answered
  if (selections.kitchenElectricalAppliances && selections.kitchenElectricalLighting) count++;
  return count;
};

