const skylightConfigData = {
  fixedDeck: { label: 'Fixed – Deck-mounted', type: 'fixed', mount: 'deck', costPerUnit: { min: 1200, max: 2200 }, description: 'Sealed IGU flush with roof plane — lowest cost, best seal, no ventilation' },
  fixedCurb: { label: 'Fixed – Curb-mounted', type: 'fixed', mount: 'curb', costPerUnit: { min: 1500, max: 2800 }, description: 'Sealed IGU on raised curb — better water shedding, easier retrofit/replacement' },
  ventingDeck: { label: 'Venting – Deck-mounted', type: 'venting', mount: 'deck', costPerUnit: { min: 2000, max: 3200 }, description: 'Operable sash flush with roof — active ventilation, requires electrical coordination' },
  ventingCurb: { label: 'Venting – Curb-mounted', type: 'venting', mount: 'curb', costPerUnit: { min: 2400, max: 3800 }, description: 'Operable sash on raised curb — maximum flexibility, highest per-unit cost' }
};

const getSkylightRiskSignals = (config) => {
  const total = Object.values(config).reduce((s, v) => s + v, 0);
  const totalVenting = (config.ventingDeck || 0) + (config.ventingCurb || 0);
  const totalCurb = (config.fixedCurb || 0) + (config.ventingCurb || 0);
  const signals = [];
  if (total >= 3) signals.push({ type: 'warning', label: 'Penetration Density', text: `${total} roof penetrations — each is a potential leak path. Coordinate flashing sequence carefully.` });
  if (totalVenting > 0) signals.push({ type: 'info', label: 'Electrical Coordination', text: `${totalVenting} venting unit${totalVenting > 1 ? 's' : ''} — requires wiring, motor circuit, and rain sensor per unit. Coordinate with electrician before close-in.` });
  if (totalCurb > 0) signals.push({ type: 'caution', label: 'Water Detail', text: `${totalCurb} curb-mounted unit${totalCurb > 1 ? 's' : ''} — curb corners are highest-risk leak points. Verify slope and flashing lap direction.` });
  return signals;
};

const getSkylightCostDelta = (config) => {
  let min = 0, max = 0;
  Object.entries(config).forEach(([key, qty]) => {
    if (qty > 0 && skylightConfigData[key]) {
      min += skylightConfigData[key].costPerUnit.min * qty;
      max += skylightConfigData[key].costPerUnit.max * qty;
    }
  });
  return { min, max };
};

