// Helper: get structural completion count for mandatory decisions
const getStructuralMandatoryCompleted = (selections) => {
  return structuralBuilderMandatoryIds.filter(id => {
    const v = selections[id];
    if (!v) return false;
    const dec = structuralBuilderDecisions[id];
    if (dec.selectMode === 'multiQty' && typeof v === 'object') return true; // any selection counts
    if (dec.selectMode === 'singleZone' && typeof v === 'object') return true;
    return true;
  }).length;
};

