              <text x="50" y="58" fill="#ef4444" fontSize="7" textAnchor="end">GASKET</text>
              {[140,180,220,260].map((x,i)=><g key={i}><circle cx={x} cy="70" r="2" fill="#3b82f6" opacity="0.5" /><line x1={x} y1="72" x2={x} y2="80" stroke="#3b82f6" strokeWidth="0.8" opacity="0.5" /></g>)}
              <text x="200" y="95" textAnchor="middle" fill="#3b82f6" fontSize="8">CONDENSATION DRIP RISK</text>
