    {Array.from({ length: count }).map((_, i) => (
      <div key={i} className="aspect-[4/3] rounded-lg flex items-center justify-center" style={{ background: `linear-gradient(145deg, ${color}22, ${color}44)`, border: `1px solid ${color}33` }}>
        <svg className="w-6 h-6 opacity-30" fill="none" stroke={color} viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
      </div>
    ))}
