// Electrical Deep Dive Dispatcher
const ElectricalDeepDiveSchematic = ({ decisionId, option, tab }) => {
  const R = {
    serviceCapacity: ElecServiceDiagram,
    panelConfig: ElecPanelDiagram,
    rewiringScope: ElecRewiringDiagram,
    lowVoltage: ElecLowVoltageDiagram,
    backupSystem: ElecBackupDiagram
  }[decisionId];
  return R ? (
    <div className="w-full aspect-[4/3] bg-white rounded-lg border border-slate-200 overflow-hidden">
      <R option={option} tab={tab} />
    </div>
  ) : null;
};

// ============================================
// COMPONENT: Electrical Plan — Deep Dive
// ============================================
const ElectricalDecisionDeepDive = ({ decision, currentValue, onClose, onValueChange }) => {
  const dd = electricalDeepDiveContent[decision.id];
  if (!dd) return null;
  const [activeTab, setActiveTab] = useState(dd.tabs[0]);
  const content = dd.content[currentValue];
  if (!content) return null;
  return (
    <div className="fixed inset-0 z-50 flex flex-col bg-white">
      <div className="shrink-0 bg-white border-b border-slate-200 px-4 pt-3 pb-2">
        <div className="flex items-center justify-between mb-2">
          <div className="flex items-center gap-2">
            <button onClick={onClose} className="p-1 -ml-1 hover:bg-slate-100 rounded-lg transition-colors"><svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg></button>
            <div><div className="text-xs text-slate-500 uppercase tracking-wide leading-none">Dive In</div><h2 className="text-base font-semibold text-slate-800 leading-tight">{decision.title}</h2></div>
          </div>
        </div>
        <div className="flex gap-2 items-center">
          <div className="flex gap-1 flex-1 overflow-x-auto">{decision.options.map(o => (<button key={o.value} onClick={() => { onValueChange(o.value); setActiveTab(dd.tabs[0]); }} className={`flex-1 py-1.5 px-2 text-xs font-medium rounded-md transition-all whitespace-nowrap ${currentValue === o.value ? 'bg-slate-800 text-white' : 'bg-slate-100 text-slate-600'}`}>{o.label}</button>))}</div>
          <div className="w-px h-6 bg-slate-200" />
          <div className="flex gap-1 overflow-x-auto">{dd.tabs.map(t => (<button key={t} onClick={() => setActiveTab(t)} className={`py-1.5 px-2 text-xs font-medium rounded-md transition-all whitespace-nowrap ${activeTab === t ? 'bg-blue-100 text-blue-700' : 'text-slate-500 hover:bg-slate-100'}`}>{t}</button>))}</div>
        </div>
      </div>
      <div className="px-3 pt-3"><ElectricalDeepDiveSchematic decisionId={decision.id} option={currentValue} tab={activeTab} /></div>
      <div className="flex-1 overflow-y-auto overscroll-contain">
        <div className="p-3 space-y-2">
          <CollapsibleSection label="What is different" badge="A" badgeColor="slate" defaultOpen={true}><ul className="space-y-2 mt-1">{content.whatIsDifferent.map((item, i) => (<li key={i} className="flex items-start gap-2 text-sm text-slate-600"><span className="text-slate-400 mt-0.5 shrink-0">•</span><span>{item}</span></li>))}</ul></CollapsibleSection>
          <CollapsibleSection label="Execution & risk notes" badge="B" badgeColor="amber" defaultOpen={true}><ul className="space-y-2 mt-1">{content.executionRisk.map((item, i) => (<li key={i} className="flex items-start gap-2 text-sm text-slate-600"><span className="text-amber-500 mt-0.5 shrink-0">⚠</span><span>{item}</span></li>))}</ul></CollapsibleSection>
          <CollapsibleSection label="How to choose" badge="C" badgeColor="blue" defaultOpen={true}>
            <div className="space-y-2 mt-1">
              <div className="bg-green-50 border border-green-200 rounded-lg p-2.5"><h4 className="text-xs font-semibold text-green-800 uppercase tracking-wide mb-1.5">✓ Works well when</h4><ul className="space-y-1">{content.howToChoose.worksWell.map((item, i) => (<li key={i} className="text-sm text-green-700 flex items-start gap-2"><span className="text-green-500 shrink-0">•</span><span>{item}</span></li>))}</ul></div>
              <div className="bg-amber-50 border border-amber-200 rounded-lg p-2.5"><h4 className="text-xs font-semibold text-amber-800 uppercase tracking-wide mb-1.5">? Consider carefully if</h4><ul className="space-y-1">{content.howToChoose.concerns.map((item, i) => (<li key={i} className="text-sm text-amber-700 flex items-start gap-2"><span className="text-amber-500 shrink-0">•</span><span>{item}</span></li>))}</ul></div>
              <div className="bg-red-50 border border-red-200 rounded-lg p-2.5"><h4 className="text-xs font-semibold text-red-800 uppercase tracking-wide mb-1.5">✗ Red flags</h4><ul className="space-y-1">{content.howToChoose.redFlags.map((item, i) => (<li key={i} className="text-sm text-red-700 flex items-start gap-2"><span className="text-red-500 shrink-0">•</span><span>{item}</span></li>))}</ul></div>
            </div>
          </CollapsibleSection>
          {content.systemsBrands && content.systemsBrands.systems.length > 0 && (
            <CollapsibleSection label="Common systems & brands" badge="D" badgeColor="gray" defaultOpen={true}>
              <div className="mt-1"><p className="text-xs text-slate-500 mb-2">{content.systemsBrands.intro}</p><div className="space-y-2">{content.systemsBrands.systems.map((s, i) => (<div key={i} className="bg-slate-50 rounded-lg p-2.5"><h4 className="text-xs font-semibold text-slate-700 uppercase tracking-wide">{s.type}</h4><p className="text-sm text-slate-600 mt-0.5">{s.brands}</p><p className="text-xs text-slate-500 mt-0.5 italic">{s.note}</p></div>))}</div></div>
            </CollapsibleSection>
          )}
        </div>
        <div className="h-20" />
      </div>
      <div className="absolute bottom-4 left-0 right-0 flex justify-center pointer-events-none">
        <button onClick={onClose} className="pointer-events-auto flex items-center gap-2 px-5 py-2.5 bg-slate-800 text-white text-sm font-medium rounded-full shadow-lg hover:bg-slate-700 transition-colors">
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>Back to Decision Card
        </button>
      </div>
    </div>
  );
};

