// Plumbing Helper Functions — Triggers, Complexity, Cross-Scene Impact
const getPlumbingTriggers = (state) => {
  const triggers = [];
  if (state.repiping === 'fullRepipe') { triggers.push({ flag: 'WALLS_CEILINGS_OPEN', label: 'Walls and ceilings must be opened for new piping', scene: 'Structural' }); triggers.push({ flag: 'ELECTRICAL_REROUTE', label: 'Existing wiring may need rerouting around new pipes', scene: 'Electrical' }); }
  if (state.repiping === 'partialRepipe') { triggers.push({ flag: 'WALL_ACCESS_NEEDED', label: 'Localized wall/ceiling access required for problem sections', scene: 'Structural' }); }
  if (state.waterHeater === 'tankless') { triggers.push({ flag: 'GAS_LINE_UPGRADE', label: 'Verify gas line capacity for tankless unit', scene: 'Electrical' }); triggers.push({ flag: 'VENTING_REQUIRED', label: 'Venting for gas tankless must be routed to exterior', scene: 'Structural' }); }
  if (state.waterHeater === 'heatPump') { triggers.push({ flag: 'ELECTRICAL_SERVICE_CHECK', label: 'Verify 200A electrical service for heat pump water heater', scene: 'Electrical' }); triggers.push({ flag: 'MECHANICAL_SPACE', label: 'Require cabinet space and air clearance for heat pump', scene: 'Structural' }); }
  if (state.sewerConnection === 'replaceLateral') { triggers.push({ flag: 'EXCAVATION_REQUIRED', label: 'Extensive yard excavation for lateral replacement', scene: 'Structural' }); }
  if (state.sewerConnection === 'connectCity') { triggers.push({ flag: 'CITY_PERMITS', label: 'City sewer connection requires permits and inspections', scene: 'Structural' }); triggers.push({ flag: 'SEPTIC_DECOMMISSION', label: 'Existing septic must be properly decommissioned', scene: 'Structural' }); }
  if (state.sewerConnection === 'upgradeSeptic') { triggers.push({ flag: 'SEPTIC_DESIGN', label: 'Soil test and engineer design required for septic upgrade', scene: 'Structural' }); }
  if (state.filtration === 'filterSoftener') { triggers.push({ flag: 'DRAIN_REQUIRED', label: 'Softener backwash requires floor drain or exterior outlet', scene: 'Structural' }); }
  return triggers;
};

const getPlumbingComplexity = (state) => {
  let score = 0;
  if (state.repiping === 'partialRepipe') score += 2;
  else if (state.repiping === 'fullRepipe') score += 3;
  if (state.waterHeater === 'tankless') score += 2;
  else if (state.waterHeater === 'heatPump') score += 2;
  if (state.sewerConnection === 'replaceLateral') score += 3;
  else if (state.sewerConnection === 'connectCity') score += 3;
  else if (state.sewerConnection === 'upgradeSeptic') score += 2;
  if (state.filtration === 'filterSoftener') score += 1;
  const level = score <= 2 ? 'Low' : score <= 5 ? 'Medium' : 'High';
  const summary = level === 'Low' ? 'Straightforward plumbing work — standard contractor scope.' : level === 'Medium' ? 'Moderate complexity — requires experienced plumber and some coordination.' : 'High complexity — major excavation and/or extensive wall access needed.';
  return { level, score, maxScore: 9, summary };
};

const getPlumbingCrossSceneImpact = (state) => {
  const impacts = [];
  const structImpacts = [];
  if (state.repiping === 'fullRepipe') structImpacts.push('Walls and ceilings opened for full pipe replacement');
  if (state.repiping === 'partialRepipe') structImpacts.push('Localized wall/ceiling openings for problem sections');
  if (state.sewerConnection === 'replaceLateral') structImpacts.push('Extensive yard excavation for new lateral line');
  if (state.sewerConnection === 'connectCity') structImpacts.push('Deep excavation to municipal sewer main');
  if (state.sewerConnection === 'upgradeSeptic') structImpacts.push('Septic tank and drain field excavation');
  if (structImpacts.length > 0) impacts.push({ scene: 'Structural', items: structImpacts });
  const elecImpacts = [];
  if (state.waterHeater === 'tankless') elecImpacts.push('Verify gas line capacity or install tankless-grade electric service');
  if (state.waterHeater === 'heatPump') elecImpacts.push('Require 200A service and dedicated 240V circuit for heat pump water heater');
  if (state.repiping === 'fullRepipe') elecImpacts.push('Electrical wiring may need rerouting around new piping');
  if (elecImpacts.length > 0) impacts.push({ scene: 'Electrical', items: elecImpacts });
  const hvacImpacts = [];
  if (state.waterHeater === 'heatPump') hvacImpacts.push('Heat pump water heater requires air intake — not suitable in sealed closets');
  if (state.repiping === 'fullRepipe') hvacImpacts.push('New pipe runs may interact with supply/return ducts in walls');
  if (hvacImpacts.length > 0) impacts.push({ scene: 'HVAC', items: hvacImpacts });
  return impacts;
};
