const PlumbingIllustrationMap = {
  repiping: RepipeScopeSVG,
  waterHeater: WaterHeaterSVG,
  sewerConnection: SewerConnectionSVG,
  filtration: FiltrationSVG
};

// ============================================
// COMPONENT: Plumbing Decision Card
// ============================================
const PlumbingDecisionCard = ({ decision, currentValue, onDeepDive }) => {
  const card = decision.cards[currentValue];
  const opt = decision.options.find(o => o.value === currentValue);
  if (!card) return null;
  const riskColors = { Low: 'bg-green-100 text-green-700 border-green-200', Medium: 'bg-amber-100 text-amber-700 border-amber-200', High: 'bg-red-100 text-red-700 border-red-200' };
  const costColors = { '$': 'bg-green-100 text-green-700 border-green-200', '$$': 'bg-amber-100 text-amber-700 border-amber-200', '$–$$': 'bg-yellow-100 text-yellow-700 border-yellow-200' };
  return (
    <div className="bg-white rounded-xl border border-slate-200 overflow-hidden">
      <div className="px-4 py-3 bg-slate-50 border-b border-slate-200">
        <div className="flex items-center justify-between">
          <div>
            <div className="text-xs text-slate-500 uppercase tracking-wide">Decision Card</div>
            <h3 className="text-lg font-semibold text-slate-800">{decision.title}: {opt.label}</h3>
          </div>
          <div className="flex gap-1.5">
            <span className={`px-2 py-0.5 text-xs font-medium rounded-full border ${costColors[card.costTier] || costColors['$$']}`}>{card.costTier}</span>
            <span className={`px-2 py-0.5 text-xs font-medium rounded-full border ${riskColors[card.riskTier] || riskColors.Medium}`}>{card.riskTier} Risk</span>
          </div>
        </div>
      </div>
      <div className="p-4 space-y-4">
        <div>
          <h4 className="text-xs font-medium text-slate-500 uppercase tracking-wide mb-1">Visual Impact</h4>
          {(() => { const IllustrationComp = PlumbingIllustrationMap[decision.id]; return IllustrationComp ? <IllustrationComp value={currentValue} /> : null; })()}
          <p className="text-sm text-slate-700">{card.visualImpact}</p>
        </div>
        <div>
          <h4 className="text-xs font-medium text-slate-500 uppercase tracking-wide mb-2">Key Trade-offs</h4>
          <ul className="space-y-1.5">{card.tradeoffs.map((t, i) => (<li key={i} className="flex items-start gap-2 text-sm text-slate-600"><span className="text-slate-400 mt-0.5">{'\u2022'}</span><span>{t}</span></li>))}</ul>
        </div>
        <div className="bg-green-50 rounded-lg p-3 border border-green-200">
          <h4 className="text-xs font-medium text-green-700 uppercase tracking-wide mb-1">When This Works Well</h4>
          <p className="text-sm text-green-800">{card.whenWorksWell}</p>
        </div>
        <div className="bg-amber-50 rounded-lg p-3 border border-amber-200">
          <h4 className="text-xs font-medium text-amber-700 uppercase tracking-wide mb-1">Main Trade-off</h4>
          <p className="text-sm text-amber-800">{card.mainTradeoff}</p>
        </div>
        {card.crossSceneImpact && card.crossSceneImpact.length > 0 && (
          <div>
            <h4 className="text-xs font-medium text-slate-500 uppercase tracking-wide mb-2">Cross-Scene Impact</h4>
            <div className="flex flex-wrap gap-1.5">
              {card.crossSceneImpact.map((imp, i) => (<span key={i} className="px-2 py-1 text-xs bg-blue-50 text-blue-700 rounded-md border border-blue-200">{imp}</span>))}
            </div>
          </div>
        )}
        <div className="bg-slate-50 rounded-lg p-3">
          <h4 className="text-xs font-medium text-slate-500 uppercase tracking-wide mb-1">Est. Delta</h4>
          <div className="flex items-baseline gap-2">
            {card.costDelta.min === 0 && card.costDelta.max <= 500 ? <span className="text-lg font-semibold text-slate-600">Baseline</span> : <span className="text-lg font-semibold text-slate-800">+${card.costDelta.min.toLocaleString()} – ${card.costDelta.max.toLocaleString()}</span>}
            <span className="text-xs text-slate-500">{card.costDelta.note}</span>
          </div>
        </div>
        {decision.hasDeepDive && (
          <button onClick={onDeepDive} className="w-full py-2.5 px-4 text-sm font-medium text-blue-600 bg-blue-50 hover:bg-blue-100 rounded-lg transition-colors flex items-center justify-center gap-2">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg>Dive In
          </button>
        )}
      </div>
    </div>
  );
};

// ============================================
// COMPONENT: Plumbing Decision Deep Dive
// ============================================
const PlumbingDecisionDeepDive = ({ decision, currentValue, onClose, onValueChange }) => {
  const dd = plumbingDeepDiveContent[decision.id];
  if (!dd) return null;
  const [activeTab, setActiveTab] = useState(dd.tabs[0]);
  const content = dd.content[currentValue];
  if (!content) return null;
  return (
    <div className="fixed inset-0 z-50 flex flex-col bg-white">
      <div className="shrink-0 bg-white border-b border-slate-200 px-4 pt-3 pb-2">
        <div className="flex items-center justify-between mb-2">
          <div className="flex items-center gap-2">
            <button onClick={onClose} className="p-1 -ml-1 hover:bg-slate-100 rounded-lg transition-colors">
              <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
            </button>
            <div>
              <div className="text-xs text-slate-500 uppercase tracking-wide leading-none">Deep Dive</div>
              <h2 className="text-base font-semibold text-slate-800 leading-tight">{decision.title}</h2>
            </div>
          </div>
        </div>
        <div className="flex gap-2 items-center">
          <div className="flex gap-1 flex-1">
            {decision.options.map(o => (
              <button key={o.value} onClick={() => { onValueChange(o.value); setActiveTab(dd.tabs[0]); }} className={`flex-1 py-1.5 px-2 text-xs font-medium rounded-md transition-all ${currentValue === o.value ? 'bg-slate-800 text-white' : 'bg-slate-100 text-slate-600'}`}>
                {o.label}
              </button>
            ))}
          </div>
          <div className="w-px h-6 bg-slate-200" />
          <div className="flex gap-1 overflow-x-auto">
            {dd.tabs.map(t => (
              <button key={t} onClick={() => setActiveTab(t)} className={`py-1.5 px-2 text-xs font-medium rounded-md transition-all whitespace-nowrap ${activeTab === t ? 'bg-blue-100 text-blue-700' : 'text-slate-500 hover:bg-slate-100'}`}>
                {t}
              </button>
            ))}
          </div>
        </div>
      </div>
      <div className="flex-1 overflow-y-auto overscroll-contain">
        <div className="p-3 space-y-2">
          {(() => { const IllustrationComp = PlumbingIllustrationMap[decision.id]; return IllustrationComp ? <div className="bg-white rounded-lg border border-slate-200 p-3 mb-2"><IllustrationComp value={currentValue} /></div> : null; })()}
          <CollapsibleSection label="What is different" badge="A" badgeColor="slate" defaultOpen={true}>
            <ul className="space-y-2 mt-1">
              {content.whatIsDifferent.map((item, i) => (
                <li key={i} className="flex items-start gap-2 text-sm text-slate-600"><span className="text-slate-400 mt-0.5 shrink-0">{'\u2022'}</span><span>{item}</span></li>
              ))}
            </ul>
          </CollapsibleSection>
          <CollapsibleSection label="Execution & risk notes" badge="B" badgeColor="amber" defaultOpen={true}>
            <ul className="space-y-2 mt-1">
              {content.executionRisk.map((item, i) => (
                <li key={i} className="flex items-start gap-2 text-sm text-slate-600"><span className="text-amber-500 mt-0.5 shrink-0">{'\u26A0'}</span><span>{item}</span></li>
              ))}
            </ul>
          </CollapsibleSection>
          <CollapsibleSection label="How to choose" badge="C" badgeColor="blue" defaultOpen={true}>
            <div className="space-y-2 mt-1">
              <div className="bg-green-50 border border-green-200 rounded-lg p-2.5">
                <h4 className="text-xs font-semibold text-green-800 uppercase tracking-wide mb-1.5">{'\u2713'} Works well when</h4>
                <ul className="space-y-1">{content.howToChoose.worksWell.map((item, i) => (<li key={i} className="text-sm text-green-700 flex items-start gap-2"><span className="text-green-500 shrink-0">{'\u2022'}</span><span>{item}</span></li>))}</ul>
              </div>
              <div className="bg-amber-50 border border-amber-200 rounded-lg p-2.5">
                <h4 className="text-xs font-semibold text-amber-800 uppercase tracking-wide mb-1.5">? Consider carefully if</h4>
                <ul className="space-y-1">{content.howToChoose.concerns.map((item, i) => (<li key={i} className="text-sm text-amber-700 flex items-start gap-2"><span className="text-amber-500 shrink-0">{'\u2022'}</span><span>{item}</span></li>))}</ul>
              </div>
              <div className="bg-red-50 border border-red-200 rounded-lg p-2.5">
                <h4 className="text-xs font-semibold text-red-800 uppercase tracking-wide mb-1.5">{'\u2717'} Red flags</h4>
                <ul className="space-y-1">{content.howToChoose.redFlags.map((item, i) => (<li key={i} className="text-sm text-red-700 flex items-start gap-2"><span className="text-red-500 shrink-0">{'\u2022'}</span><span>{item}</span></li>))}</ul>
              </div>
            </div>
          </CollapsibleSection>
          <CollapsibleSection label="Common systems & brands" badge="D" badgeColor="gray" defaultOpen={true}>
            <div className="mt-1">
              <p className="text-xs text-slate-500 mb-2">{content.systemsBrands.intro}</p>
              <div className="space-y-2">
                {content.systemsBrands.systems.map((s, i) => (
                  <div key={i} className="bg-slate-50 rounded-lg p-2.5">
                    <h4 className="text-xs font-semibold text-slate-700 uppercase tracking-wide">{s.type}</h4>
                    <p className="text-sm text-slate-600 mt-0.5">{s.brands}</p>
                    <p className="text-xs text-slate-500 mt-0.5 italic">{s.note}</p>
                  </div>
                ))}
              </div>
            </div>
          </CollapsibleSection>
        </div>
        <div className="h-20" />
      </div>
      <div className="absolute bottom-4 left-0 right-0 flex justify-center pointer-events-none">
        <button onClick={onClose} className="pointer-events-auto flex items-center gap-2 px-5 py-2.5 bg-slate-800 text-white text-sm font-medium rounded-full shadow-lg hover:bg-slate-700 transition-colors">
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>Back to Decision Card
        </button>
      </div>
    </div>
  );
};

const ElectricalPreAssessment = ({ onContinue, onBack }) => {
  // ── Question state ──
  const [q1Layout, setQ1Layout] = useState(null);       // 'none' | 'minor' | 'major'
  const [q2Lighting, setQ2Lighting] = useState(null);    // 'replace' | 'addSeveral' | 'fullNew'
  const [q3WiringAge, setQ3WiringAge] = useState(null);  // '2000plus' | '1980to2000' | 'pre1980' | 'knobTube'
  const [q4WallsOpen, setQ4WallsOpen] = useState(null);  // 'yes' | 'no'
  const [q5Loads, setQ5Loads] = useState([]);             // multi-select array
  const [q6Service, setQ6Service] = useState(null);       // '100a' | '200a' | '400a' | 'notSure'
  const [showResults, setShowResults] = useState(false);
  const [currentStep, setCurrentStep] = useState(0);

  // ── Question definitions ──
  const questions = [
    { id: 'q1', label: 'Layout Changes', desc: 'Are you making changes to your floor plan that affect where outlets or switches need to be?', options: [
      { value: 'none', label: 'No layout changes', desc: 'Keeping walls and room layout as-is' },
      { value: 'minor', label: 'Minor relocations', desc: 'Moving a few outlets or switches' },
      { value: 'major', label: 'Major layout change', desc: 'Adding or removing walls, changing room layout' }
    ]},
    { id: 'q2', label: 'Lighting Scope', desc: 'What level of lighting work are you planning?', options: [
      { value: 'replace', label: 'Replace fixtures only', desc: 'Swapping existing fixtures for new ones' },
      { value: 'addSeveral', label: 'Adding new fixtures', desc: 'Installing several new light fixtures in existing or new locations' },
      { value: 'fullNew', label: 'Full new lighting layout', desc: 'Completely redesigning the lighting plan' }
    ]},
    { id: 'q3', label: 'Wiring Age', desc: 'When was your home\'s electrical wiring last updated?', options: [
      { value: '2000plus', label: '2000 or newer', desc: 'Modern wiring, likely up to current code' },
      { value: '1980to2000', label: '1980–2000', desc: 'May have older insulation types but generally serviceable' },
      { value: 'pre1980', label: 'Before 1980', desc: 'Higher chance of outdated wiring methods and materials' },
      { value: 'knobTube', label: 'Knob & tube / Unknown', desc: 'Very old wiring or you\'re not sure of the age' }
    ]},
    { id: 'q4', label: 'Wall Access', desc: 'Are walls being opened as part of this project anyway?', options: [
      { value: 'yes', label: 'Yes', desc: 'Walls will be opened for other renovation work' },
      { value: 'no', label: 'No', desc: 'Walls are staying closed' }
    ]},
    { id: 'q5', label: 'New Electrical Loads', desc: 'Are you adding any of these high-draw systems? Select all that apply.', multi: true, options: [
      { value: 'evCharger', label: 'EV charger' },
      { value: 'heatPump', label: 'Heat pump HVAC' },
      { value: 'electricDryer', label: 'Electric dryer' },
      { value: 'inductionCooktop', label: 'Induction cooktop' },
      { value: 'doubleOven', label: 'Double oven' },
      { value: 'tanklessWaterHeater', label: 'Tankless electric water heater' },
      { value: 'poolEquipment', label: 'Pool equipment' },
      { value: 'adu', label: 'ADU addition' },
      { value: 'none', label: 'None of the above' }
    ]},
    { id: 'q6', label: 'Current Service', desc: 'What is your home\'s current electrical service size?', options: [
      { value: '100a', label: '100A', desc: 'Typical in older homes' },
      { value: '200a', label: '200A', desc: 'Modern standard for most homes' },
      { value: '400a', label: '400A', desc: 'Heavy-duty / multi-structure' },
      { value: 'notSure', label: 'Not sure', desc: 'You don\'t know your service size' }
    ]}
  ];

  const answers = [q1Layout, q2Lighting, q3WiringAge, q4WallsOpen, q5Loads, q6Service];
  const setters = [setQ1Layout, setQ2Lighting, setQ3WiringAge, setQ4WallsOpen, null, setQ6Service];
  const isStepComplete = (step) => {
    if (step === 4) return q5Loads.length > 0;
    return answers[step] !== null;
  };
  const allComplete = answers.every((a, i) => i === 4 ? q5Loads.length > 0 : a !== null);

  // ── Internal scoring (never exposed to user) ──
  const computeResults = () => {
    // Dimension 1: Rewiring Likelihood
    const q1Score = q1Layout === 'none' ? 0 : q1Layout === 'minor' ? 2 : 4;
    const q2Score = q2Lighting === 'replace' ? 0 : q2Lighting === 'addSeveral' ? 2 : 3;
    const q3Score = q3WiringAge === '2000plus' ? 0 : q3WiringAge === '1980to2000' ? 1 : q3WiringAge === 'pre1980' ? 3 : 5;
    const rewiringRaw = q1Score + q2Score + q3Score;
    let rewiringTier = rewiringRaw <= 3 ? 'Unlikely' : rewiringRaw <= 6 ? 'Possible' : 'Likely';
    // Wall-opening conditional: only elevates if wiring is old
    const oldWiring = q3WiringAge === 'pre1980' || q3WiringAge === 'knobTube';
    if (oldWiring && q4WallsOpen === 'yes' && rewiringTier !== 'Likely') {
      rewiringTier = rewiringTier === 'Unlikely' ? 'Possible' : 'Likely';
    }

    // Dimension 2: Load Expansion
    const loadScores = { evCharger: 5, heatPump: 5, electricDryer: 3, inductionCooktop: 3, doubleOven: 3, tanklessWaterHeater: 6, poolEquipment: 3, adu: 6, none: 0 };
    const loadTotal = q5Loads.reduce((s, v) => s + (loadScores[v] || 0), 0);
    const loadTier = loadTotal <= 4 ? 'Light' : loadTotal <= 10 ? 'Moderate' : 'Heavy';

    // Dimension 3: Service Upgrade Determination
    let upgradeTier = 'Unlikely';
    if (loadTier === 'Heavy' && q6Service === '100a') upgradeTier = 'Likely';
    else if (loadTier === 'Heavy' && q6Service === '200a') upgradeTier = 'Possible';
    else if (loadTier === 'Moderate' && q6Service === '100a') upgradeTier = 'Possible';
    else if (q6Service === 'notSure' && (loadTier === 'Moderate' || loadTier === 'Heavy')) upgradeTier = 'Possible';

    return { rewiringTier, loadTier, upgradeTier };
  };

  const handleSubmit = () => { setShowResults(true); };

  // ── Tier color helpers ──
  const tierColor = (tier) => {
    if (tier === 'Likely' || tier === 'Heavy') return 'text-red-700 bg-red-50 border-red-200';
    if (tier === 'Possible' || tier === 'Moderate') return 'text-amber-700 bg-amber-50 border-amber-200';
    return 'text-green-700 bg-green-50 border-green-200';
  };
  const tierDot = (tier) => {
    if (tier === 'Likely' || tier === 'Heavy') return 'bg-red-500';
    if (tier === 'Possible' || tier === 'Moderate') return 'bg-amber-500';
    return 'bg-green-500';
  };

  // ── Handle multi-select for Q5 ──
  const toggleLoad = (value) => {
    if (value === 'none') { setQ5Loads(['none']); return; }
    setQ5Loads(prev => {
      const filtered = prev.filter(v => v !== 'none');
      return filtered.includes(value) ? filtered.filter(v => v !== value) : [...filtered, value];
    });
  };

  // ── Results view ──
  if (showResults) {
    const { rewiringTier, loadTier, upgradeTier } = computeResults();
    // Dynamic explanations
    const rewiringExpl = rewiringTier === 'Likely' ? 'Based on layout changes and/or older wiring, a partial or full rewiring evaluation is recommended.'
      : rewiringTier === 'Possible' ? 'Some project elements may require additional wiring work.'
      : 'Your existing wiring is likely adequate for the planned scope.';
    const upgradeExpl = upgradeTier === 'Likely' ? 'Your planned additions may exceed your current service capacity. A panel and service review is strongly recommended.'
      : upgradeTier === 'Possible' ? 'A service capacity review may be necessary depending on final load calculations.'
      : 'Your current service size appears sufficient for the planned changes.';

    return (
      <div className="min-h-screen bg-slate-50">
        <header className="bg-white border-b border-slate-200 px-4 py-3 sticky top-0 z-10">
          <div className="max-w-lg mx-auto flex items-center gap-3">
            <button onClick={() => setShowResults(false)} className="p-1 -ml-1 hover:bg-slate-100 rounded-lg transition-colors shrink-0">
              <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
            </button>
            <div><h1 className="text-lg font-semibold text-slate-800">Pre-Assessment Results</h1><p className="text-xs text-slate-500">Electrical Plan</p></div>
          </div>
        </header>
        <main className="max-w-lg mx-auto px-4 py-4 space-y-4">
          {/* Result Card */}
          <div className="bg-white rounded-xl border border-slate-200 overflow-hidden">
            <div className="px-4 py-3 bg-gradient-to-r from-slate-50 to-blue-50 border-b border-slate-200">
              <h2 className="text-base font-semibold text-slate-800 flex items-center gap-2">⚡ Your Electrical Scope Snapshot</h2>
              <p className="text-xs text-slate-500 mt-0.5">Based on your project details</p>
            </div>
            <div className="p-4 space-y-3">
              {/* Rewiring Likelihood */}
              <div className={`rounded-lg border p-3 ${tierColor(rewiringTier)}`}>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <div className={`w-2 h-2 rounded-full ${tierDot(rewiringTier)}`} />
                    <span className="text-xs font-medium uppercase tracking-wide">Rewiring Likelihood</span>
                  </div>
                  <span className="text-sm font-semibold">{rewiringTier}</span>
                </div>
              </div>
              {/* Load Expansion Level */}
              <div className={`rounded-lg border p-3 ${tierColor(loadTier)}`}>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <div className={`w-2 h-2 rounded-full ${tierDot(loadTier)}`} />
                    <span className="text-xs font-medium uppercase tracking-wide">Load Expansion Level</span>
                  </div>
                  <span className="text-sm font-semibold">{loadTier}</span>
                </div>
              </div>
              {/* Service Upgrade Likelihood */}
              <div className={`rounded-lg border p-3 ${tierColor(upgradeTier)}`}>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <div className={`w-2 h-2 rounded-full ${tierDot(upgradeTier)}`} />
                    <span className="text-xs font-medium uppercase tracking-wide">Service Upgrade Likelihood</span>
                  </div>
                  <span className="text-sm font-semibold">{upgradeTier}</span>
                </div>
              </div>
            </div>
          </div>

          {/* What This Means */}
          <div className="bg-white rounded-xl border border-slate-200 overflow-hidden">
            <div className="px-4 py-3 border-b border-slate-100">
              <h3 className="text-sm font-semibold text-slate-800">What This Means</h3>
            </div>
            <div className="p-4 space-y-3">
              <div className="flex items-start gap-3">
                <div className={`w-1.5 rounded-full self-stretch shrink-0 ${rewiringTier === 'Likely' ? 'bg-red-400' : rewiringTier === 'Possible' ? 'bg-amber-400' : 'bg-green-400'}`} />
                <div>
                  <div className="text-xs font-medium text-slate-500 uppercase tracking-wide mb-0.5">Rewiring</div>
                  <p className="text-sm text-slate-600">{rewiringExpl}</p>
                </div>
              </div>
              <div className="flex items-start gap-3">
                <div className={`w-1.5 rounded-full self-stretch shrink-0 ${upgradeTier === 'Likely' ? 'bg-red-400' : upgradeTier === 'Possible' ? 'bg-amber-400' : 'bg-green-400'}`} />
                <div>
                  <div className="text-xs font-medium text-slate-500 uppercase tracking-wide mb-0.5">Service Upgrade</div>
                  <p className="text-sm text-slate-600">{upgradeExpl}</p>
                </div>
              </div>
            </div>
          </div>

          {/* Primary Decisions to Review */}
          <div className="bg-white rounded-xl border border-slate-200 overflow-hidden">
            <div className="px-4 py-3 border-b border-slate-100">
              <h3 className="text-sm font-semibold text-slate-800">Primary Decisions to Review</h3>
            </div>
            <div className="p-4">
              <div className="space-y-2">
                {['Service Capacity', 'Panel Configuration', 'Circuit Planning', 'Future Load Strategy'].map((item, i) => (
                  <div key={i} className="flex items-center gap-2.5 py-1.5">
                    <div className="w-6 h-6 rounded-md bg-blue-50 border border-blue-200 flex items-center justify-center shrink-0">
                      <span className="text-xs font-semibold text-blue-600">{i + 1}</span>
                    </div>
                    <span className="text-sm text-slate-700">{item}</span>
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* Continue Button */}
          <button onClick={onContinue} className="w-full py-3 px-4 bg-slate-800 text-white text-sm font-medium rounded-xl hover:bg-slate-700 transition-colors flex items-center justify-center gap-2">
            Continue to Electrical Planning
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg>
          </button>
        </main>
        <div className="h-20" />
      </div>
    );
  }

  // ── Question flow view ──
  const q = questions[currentStep];
  const isMulti = q.multi;
  const currentAnswer = answers[currentStep];

  return (
    <div className="min-h-screen bg-slate-50">
      <header className="bg-white border-b border-slate-200 px-4 py-3 sticky top-0 z-10">
        <div className="max-w-lg mx-auto">
          <div className="flex items-center gap-3 mb-3">
            <button onClick={currentStep === 0 ? onBack : () => setCurrentStep(s => s - 1)} className="p-1 -ml-1 hover:bg-slate-100 rounded-lg transition-colors shrink-0">
              <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
            </button>
            <div className="flex-1">
              <h1 className="text-lg font-semibold text-slate-800">Electrical Pre-Assessment</h1>
              <p className="text-xs text-slate-500">Question {currentStep + 1} of {questions.length}</p>
            </div>
          </div>
          {/* Step indicators */}
          <div className="flex gap-1">
            {questions.map((_, i) => (
              <div key={i} className={`h-1 flex-1 rounded-full transition-all ${i < currentStep ? 'bg-slate-800' : i === currentStep ? 'bg-blue-500' : isStepComplete(i) ? 'bg-slate-400' : 'bg-slate-200'}`} />
            ))}
          </div>
        </div>
      </header>
      <main className="max-w-lg mx-auto px-4 py-6">
        {/* Question card */}
        <div className="mb-4">
          <div className="inline-block px-2 py-0.5 bg-slate-100 rounded text-[11px] font-medium text-slate-500 uppercase tracking-wide mb-2">{q.label}</div>
          <h2 className="text-base font-semibold text-slate-800 leading-snug">{q.desc}</h2>
        </div>

        {/* Options */}
        <div className="space-y-2">
          {q.options.map(opt => {
            const isSelected = isMulti ? q5Loads.includes(opt.value) : currentAnswer === opt.value;
            return (
              <button key={opt.value} onClick={() => {
                if (isMulti) { toggleLoad(opt.value); }
                else { setters[currentStep](opt.value); }
              }} className={`w-full text-left p-3.5 rounded-xl border-2 transition-all ${isSelected ? 'border-slate-800 bg-slate-50 shadow-sm' : 'border-slate-200 bg-white hover:border-slate-300'}`}>
                <div className="flex items-center gap-3">
                  <div className={`w-5 h-5 rounded-${isMulti ? 'md' : 'full'} border-2 flex items-center justify-center shrink-0 transition-all ${isSelected ? 'border-slate-800 bg-slate-800' : 'border-slate-300'}`}>
                    {isSelected && <svg className="w-3 h-3 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>}
                  </div>
                  <div>
                    <div className={`text-sm font-medium ${isSelected ? 'text-slate-800' : 'text-slate-700'}`}>{opt.label}</div>
                    {opt.desc && <div className="text-xs text-slate-500 mt-0.5">{opt.desc}</div>}
                  </div>
                </div>
              </button>
            );
          })}
        </div>

        {/* Navigation */}
        <div className="mt-6 flex gap-3">
          {currentStep < questions.length - 1 ? (
            <button onClick={() => setCurrentStep(s => s + 1)} disabled={!isStepComplete(currentStep)} className={`flex-1 py-3 px-4 text-sm font-medium rounded-xl transition-all flex items-center justify-center gap-2 ${isStepComplete(currentStep) ? 'bg-slate-800 text-white hover:bg-slate-700' : 'bg-slate-100 text-slate-400 cursor-not-allowed'}`}>
              Next
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg>
            </button>
          ) : (
            <button onClick={handleSubmit} disabled={!allComplete} className={`flex-1 py-3 px-4 text-sm font-medium rounded-xl transition-all flex items-center justify-center gap-2 ${allComplete ? 'bg-slate-800 text-white hover:bg-slate-700' : 'bg-slate-100 text-slate-400 cursor-not-allowed'}`}>
              View Results
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg>
            </button>
          )}
        </div>

        {/* Skip to results if all answered */}
        {allComplete && !showResults && currentStep < questions.length - 1 && (
          <button onClick={handleSubmit} className="w-full mt-3 py-2 text-xs text-blue-600 font-medium hover:underline">
            All questions answered — view results now
          </button>
        )}
      </main>
      <div className="h-20" />
    </div>
  );
};

const SceneIndexPage = ({ onSelectScene }) => {
  const sceneById = Object.fromEntries(sceneIndexItems.map(s => [s.id, s]));

  const sections = [
    {
      title: 'Core Systems',
      subtitle: 'Structural and envelope decisions. Errors here are costly to reverse.',
      sceneIds: ['structural', 'wallAssembly', 'roofing', 'openings'],
    },
    {
      title: 'MEP Systems',
      subtitle: 'Infrastructure and coordination systems. Determines long-term flexibility.',
      sceneIds: ['electrical-mep', 'hvac', 'plumbing', 'lighting'],
    },
    {
      title: 'Interior & Finish',
      subtitle: 'Finish-level decisions. Higher flexibility and later-stage selection.',
      sceneIds: ['flooring', 'kitchen', 'bathroom'],
    },
  ];

  const preAssessmentSceneIds = new Set(['roofing', 'hvac', 'plumbing', 'electrical-mep']);
  const activeSceneIds = new Set(['bathroom', 'kitchen', 'structural', 'wallAssembly', 'flooring', 'roofing', 'openings', 'lighting', 'electrical-mep', 'hvac', 'plumbing']);

  const SceneCard = ({ scene }) => {
    const isActive = activeSceneIds.has(scene.id);
    const hasPreAssessment = preAssessmentSceneIds.has(scene.id);
    return (
      <button onClick={() => onSelectScene(scene.id)} className="w-full flex items-center gap-3.5 p-3.5 bg-white rounded-xl border border-slate-200 hover:border-slate-300 hover:shadow-sm transition-all text-left group min-h-[68px]">
        <div className={`w-10 h-10 rounded-lg flex items-center justify-center shrink-0 ${isActive ? 'bg-blue-100' : 'bg-slate-100'}`}>
          <svg className={`w-5 h-5 ${isActive ? 'text-blue-600' : 'text-slate-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d={scene.icon} /></svg>
        </div>
        <div className="flex-1 min-w-0">
          <div className={`text-sm font-medium leading-tight ${isActive ? 'text-slate-800 group-hover:text-blue-700' : 'text-slate-700'}`}>{scene.name}</div>
          <div className="flex items-center gap-2 mt-0.5 flex-wrap">
            <span className={`text-xs ${isActive ? 'text-blue-600' : 'text-slate-400'}`}>{scene.subtitle}</span>
            {hasPreAssessment && <span className="text-[10px] font-medium text-blue-600 bg-blue-50 px-1.5 py-0.5 rounded-full leading-none whitespace-nowrap">Pre-Assessment</span>}
          </div>
        </div>
        <svg className={`w-4 h-4 shrink-0 ${isActive ? 'text-slate-400 group-hover:text-blue-500' : 'text-slate-300'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg>
      </button>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-10">
        <div className="max-w-2xl mx-auto px-4 py-3">
          <h1 className="text-lg font-semibold text-slate-800">Scenes</h1>
          <p className="text-xs text-slate-500">Explore decision frameworks</p>
        </div>
      </header>
      <main className="max-w-2xl mx-auto px-4 py-6 space-y-8">
        {sections.map((section, idx) => (
          <div key={idx}>
            <div className="mb-3">
              <h2 className="text-base font-semibold text-slate-800">{section.title}</h2>
              <p className="text-xs text-slate-400 mt-0.5">{section.subtitle}</p>
              <div className="mt-2 border-b border-slate-200" />
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
              {section.sceneIds.map(id => {
                const scene = sceneById[id];
                return scene ? <SceneCard key={id} scene={scene} /> : null;
              })}
            </div>
          </div>
        ))}
      </main>
      <div className="h-20" />
    </div>
  );
};

// ============================================
// COMPONENT: Scene Placeholder Page (non-Bathroom)
// ============================================
const ScenePlaceholderPage = ({ sceneId, onBack }) => {
  const scene = sceneIndexItems.find(s => s.id === sceneId);
  const name = scene ? scene.name : sceneId;
  return (
    <div className="min-h-screen bg-slate-50">
      <header className="bg-white border-b border-slate-200 px-4 py-3 sticky top-0 z-10">
        <div className="max-w-lg mx-auto flex items-center gap-3">
          <button onClick={onBack} className="p-1 -ml-1 hover:bg-slate-100 rounded-lg transition-colors shrink-0">
            <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
          </button>
          <div><h1 className="text-lg font-semibold text-slate-800">{name}</h1><p className="text-xs text-slate-500">Scene</p></div>
        </div>
      </header>
      <main className="max-w-lg mx-auto px-4 py-16 flex flex-col items-center justify-center text-center">
        <div className="w-14 h-14 rounded-2xl bg-slate-100 flex items-center justify-center mb-4">
          <svg className="w-7 h-7 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d={scene ? scene.icon : 'M12 6v6m0 0v6m0-6h6m-6 0H6'} /></svg>
        </div>
        <h2 className="text-base font-semibold text-slate-700">{name}</h2>
        <p className="text-sm text-slate-400 mt-1">Coming soon</p>
      </main>
      <div className="h-20" />
    </div>
  );
};

