// ============================================
// COMPONENT: Insights Index Page (Gallery)
// ============================================
const INSIGHT_SORT_OPTIONS = [
  { value: 'relevant', label: 'Most Relevant' },
  { value: 'helpful', label: 'Most Helpful' },
  { value: 'newest', label: 'Newest' },
];

const computeRelevanceScore = (insight, query) => {
  if (!query) return 0;
  const q = query.toLowerCase();
  let score = 0;
  if (insight.title.toLowerCase().includes(q)) score += 10;
  if (insight.summary.toLowerCase().includes(q)) score += 5;
  if ((insight.contextTags || []).some(t => t.toLowerCase().includes(q))) score += 3;
  if (insight.perspective.toLowerCase().includes(q)) score += 2;
  return score;
};

