// ============================================
// SHARED: CasesListContent — reused by Homeowner Cases & Provider Community → Cases
// ============================================
const CasesListContent = ({ onSelectCase, embedded }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedRegion, setSelectedRegion] = useState('All');
  const [selectedProjectType, setSelectedProjectType] = useState('All');
  const [selectedScopes, setSelectedScopes] = useState([]);
  const [selectedSort, setSelectedSort] = useState('newest');
  const [filtersExpanded, setFiltersExpanded] = useState(false);

  const toggleScope = (s) => setSelectedScopes(prev => prev.includes(s) ? prev.filter(x => x !== s) : [...prev, s]);
  const hasActiveFilters = searchQuery || selectedRegion !== 'All' || selectedProjectType !== 'All' || selectedScopes.length > 0;
  const clearAll = () => { setSearchQuery(''); setSelectedRegion('All'); setSelectedProjectType('All'); setSelectedScopes([]); setSelectedSort('newest'); };

  const filtered = fullCaseRecords.filter(c => {
    if (selectedRegion !== 'All' && c.location.regionTag !== selectedRegion) return false;
    if (selectedProjectType !== 'All' && c.projectType !== selectedProjectType) return false;
    if (selectedScopes.length > 0 && !selectedScopes.some(s => c.scopes.includes(s))) return false;
    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase();
      const haystack = [c.title, c.location.city, c.location.state, c.location.regionTag, c.projectType, ...c.scopes].join(' ').toLowerCase();
      if (!haystack.includes(q)) return false;
    }
    return true;
  });

  const sorted = [...filtered].sort((a, b) => {
    if (selectedSort === 'newest') return b.yearCompleted - a.yearCompleted;
    if (selectedSort === 'cost-high') {
      if (a.totalCost == null && b.totalCost == null) return 0;
      if (a.totalCost == null) return 1;
      if (b.totalCost == null) return -1;
      return b.totalCost - a.totalCost;
    }
    if (selectedSort === 'cost-low') {
      if (a.totalCost == null && b.totalCost == null) return 0;
      if (a.totalCost == null) return 1;
      if (b.totalCost == null) return -1;
      return a.totalCost - b.totalCost;
    }
    return 0;
  });

  return (
    <>
      {/* Search + Filters */}
      <div className={embedded ? 'sticky top-[105px] z-[8] bg-slate-50 -mx-4 px-4 pb-3 pt-1' : ''}>
        <div className="relative mb-2">
          <svg className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
          <input
            type="text"
            value={searchQuery}
            onChange={e => setSearchQuery(e.target.value)}
            placeholder="Search cases (title, city, scope)..."
            className="w-full text-sm border border-slate-200 rounded-lg pl-9 pr-3 py-2 focus:outline-none focus:border-blue-400 focus:ring-1 focus:ring-blue-100 bg-slate-50"
          />
          {searchQuery && (
            <button onClick={() => setSearchQuery('')} className="absolute right-2.5 top-1/2 -translate-y-1/2 p-0.5 hover:bg-slate-200 rounded transition-colors">
              <svg className="w-3.5 h-3.5 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
            </button>
          )}
        </div>
        <div className="flex items-center justify-between gap-2">
          <button onClick={() => setFiltersExpanded(!filtersExpanded)} className={`flex items-center gap-1.5 py-1 px-2.5 text-xs font-medium rounded-full border transition-all ${filtersExpanded || hasActiveFilters ? 'bg-blue-50 text-blue-700 border-blue-200' : 'bg-white text-slate-600 border-slate-200 hover:border-slate-300'}`}>
            <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" /></svg>
            Filters{hasActiveFilters ? ' ●' : ''}
          </button>
          {hasActiveFilters && (
            <button onClick={clearAll} className="text-xs text-blue-600 font-medium hover:text-blue-800 transition-colors">Clear all</button>
          )}
          <div className="flex-1" />
          <span className="text-xs text-slate-500 tabular-nums shrink-0 mr-2">{sorted.length} of {fullCaseRecords.length}</span>
          <select value={selectedSort} onChange={e => setSelectedSort(e.target.value)} className="text-xs border border-slate-200 rounded-lg py-1 pl-2 pr-6 bg-white text-slate-600 focus:outline-none focus:border-blue-400 cursor-pointer">
            {SORT_OPTIONS.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}
          </select>
        </div>
        {filtersExpanded && (
          <div className="space-y-2.5 border-t border-slate-100 pt-2.5 mt-2.5">
            <div>
              <div className="text-[10px] font-semibold text-slate-500 uppercase tracking-wider mb-1">Region</div>
              <div className="flex gap-1.5 flex-wrap">
                <FilterChip label="All" active={selectedRegion === 'All'} onClick={() => setSelectedRegion('All')} />
                {REGION_OPTIONS.map(r => <FilterChip key={r} label={r} active={selectedRegion === r} onClick={() => setSelectedRegion(selectedRegion === r ? 'All' : r)} />)}
              </div>
            </div>
            <div>
              <div className="text-[10px] font-semibold text-slate-500 uppercase tracking-wider mb-1">Project Type</div>
              <div className="flex gap-1.5 flex-wrap">
                <FilterChip label="All" active={selectedProjectType === 'All'} onClick={() => setSelectedProjectType('All')} />
                {PROJECT_TYPE_OPTIONS.map(p => <FilterChip key={p} label={p} active={selectedProjectType === p} onClick={() => setSelectedProjectType(selectedProjectType === p ? 'All' : p)} />)}
              </div>
            </div>
            <div>
              <div className="text-[10px] font-semibold text-slate-500 uppercase tracking-wider mb-1">Scope <span className="font-normal text-slate-400">(multi-select)</span></div>
              <div className="flex gap-1.5 flex-wrap">
                {SCOPE_OPTIONS.map(s => <FilterChip key={s} label={s} active={selectedScopes.includes(s)} onClick={() => toggleScope(s)} />)}
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Results */}
      {sorted.length === 0 ? (
        <div className="text-center py-16">
          <svg className="w-10 h-10 text-slate-300 mx-auto mb-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
          <p className="text-sm text-slate-500">No cases match your filters.</p>
          <button onClick={clearAll} className="mt-2 text-sm text-blue-600 font-medium hover:text-blue-800">Clear all filters</button>
        </div>
      ) : (
        <div className="grid grid-cols-2 gap-3 mt-3">
          {sorted.map(c => <CaseCard key={c.id} caseData={c} onSelect={onSelectCase} />)}
        </div>
      )}
    </>
  );
};

// ============================================
// PAGE: Homeowner Insights Index (uses shared InsightsListContent + page-level + Post CTA)
// ============================================
const InsightsIndexPage = ({ onSelectInsight, onSelectPublisher, onCompose }) => {
  return (
    <div className="min-h-screen bg-slate-50">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-10">
        <div className="max-w-lg mx-auto px-4 py-3">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-lg font-semibold text-slate-800">Insights</h1>
              <p className="text-xs text-slate-500">Perspectives on renovation decisions</p>
            </div>
            {onCompose && (
              <button onClick={onCompose} className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold text-white bg-slate-800 rounded-lg hover:bg-slate-700 transition-colors">
                <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
                Post
              </button>
            )}
          </div>
        </div>
      </header>
      <main className="max-w-lg mx-auto px-4 py-4">
        <InsightsListContent onSelectInsight={onSelectInsight} onSelectPublisher={onSelectPublisher} />
      </main>
      <div className="h-20" />
    </div>
  );
};

// ============================================
// COMPONENT: Insight Review Page (Detail)
// ============================================
const InsightReviewPage = ({ insightId, onBack, onSelectPublisher }) => {
  const insight = insightsData.find(i => i.id === insightId);
  const [liked, setLiked] = useState(false);
  const [localLikeCount, setLocalLikeCount] = useState(insight ? insight.likeCount : 0);
  const [commentText, setCommentText] = useState('');
  const [localComments, setLocalComments] = useState(insight ? insight.comments : []);

  if (!insight) return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center">
      <div className="text-center"><p className="text-slate-500 text-sm">Insight not found</p><button onClick={onBack} className="mt-3 text-blue-600 text-sm font-medium">Go back</button></div>
    </div>
  );

  const perspectiveColors = {
    Homeowner: 'bg-emerald-100 text-emerald-700',
    GC: 'bg-orange-100 text-orange-700',
    Designer: 'bg-purple-100 text-purple-700',
    Vendor: 'bg-sky-100 text-sky-700',
    Agent: 'bg-rose-100 text-rose-700',
  };

  const handleLike = () => {
    if (liked) { setLiked(false); setLocalLikeCount(c => c - 1); }
    else { setLiked(true); setLocalLikeCount(c => c + 1); }
  };

  const handleAddComment = () => {
    if (!commentText.trim()) return;
    setLocalComments(prev => [...prev, { id: `ic-${Date.now()}`, author: 'You', text: commentText.trim(), time: 'Just now' }]);
    setCommentText('');
  };

  const relatedCases = (insight.relatedCaseIds || []).map(id => fullCaseRecords.find(c => c.id === id)).filter(Boolean);
  const relatedDecisions = (insight.relatedDecisionIds || []).map(id => decisions[id]).filter(Boolean);

  return (
    <div className="min-h-screen bg-slate-50">
      <header className="bg-white border-b border-slate-200 px-4 py-3 sticky top-0 z-10">
        <div className="max-w-lg mx-auto flex items-center gap-3">
          <button onClick={onBack} className="p-1 -ml-1 hover:bg-slate-100 rounded-lg transition-colors shrink-0">
            <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
          </button>
          <div className="flex-1 min-w-0">
            <h1 className="text-base font-semibold text-slate-800 truncate">Insight</h1>
            <p className="text-xs text-slate-500">{insight.perspective} perspective</p>
          </div>
        </div>
      </header>

      <main className="max-w-lg mx-auto px-4 py-4 space-y-4">
        {/* Title & Tags */}
        <section className="bg-white rounded-xl border border-slate-200 overflow-hidden">
          <div className="p-4">
            <div className="flex items-start gap-2 mb-3 flex-wrap">
              <span className={`inline-block px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wider rounded-full ${perspectiveColors[insight.perspective] || 'bg-slate-100 text-slate-600'}`}>{insight.perspective}</span>
              {insight.contextTags.map(tag => (
                <span key={tag} className="inline-block px-2 py-0.5 text-[10px] font-medium text-slate-500 bg-slate-100 rounded-full">{tag}</span>
              ))}
            </div>
            <h2 className="text-lg font-semibold text-slate-800 leading-snug">{insight.title}</h2>
            {/* Author byline */}
            {insight.author && (
              <button
                onClick={() => onSelectPublisher && onSelectPublisher(insight.author.id)}
                className="flex items-center gap-2.5 mt-3 pt-3 border-t border-slate-100 group/author w-full text-left"
              >
                <div className="w-8 h-8 rounded-full bg-slate-200 flex items-center justify-center shrink-0 group-hover/author:bg-slate-300 transition-colors">
                  <span className="text-[10px] font-bold text-slate-500">{insight.author.avatarInitials}</span>
                </div>
                <div className="flex-1 min-w-0">
                  <div className="text-sm font-medium text-slate-700 group-hover/author:text-blue-700 transition-colors">{insight.author.name}</div>
                  <div className="text-[11px] text-slate-400">{insight.author.roleLabel}{insight.publishedAt && <> · {new Date(insight.publishedAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}</>}</div>
                </div>
                <svg className="w-4 h-4 text-slate-300 group-hover/author:text-blue-500 transition-colors shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg>
              </button>
            )}
          </div>
        </section>

        {/* Summary */}
        <section className="bg-white rounded-xl border border-slate-200 overflow-hidden">
          <div className="px-4 py-3 border-b border-slate-200 bg-slate-50"><h3 className="text-sm font-medium text-slate-700">Summary</h3></div>
          <div className="p-4"><p className="text-sm text-slate-600 leading-relaxed">{insight.summary}</p></div>
        </section>

        {/* Main Content */}
        <section className="bg-white rounded-xl border border-slate-200 overflow-hidden">
          <div className="p-4 space-y-3">
            {insight.content.split('\n\n').map((para, i) => (
              <p key={i} className="text-sm text-slate-700 leading-relaxed">{para}</p>
            ))}
          </div>
        </section>

        {/* Context Box */}
        <section className="bg-white rounded-xl border border-slate-200 overflow-hidden">
          <div className="px-4 py-3 border-b border-slate-200 bg-slate-50"><h3 className="text-sm font-medium text-slate-700">Context</h3></div>
          <div className="p-4 space-y-4">
            {/* Related Cases */}
            {relatedCases.length > 0 && (
              <div>
                <h4 className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-1.5">Related Cases</h4>
                <div className="space-y-1">
                  {relatedCases.map(c => (
                    <div key={c.id} className="flex items-center gap-2 py-1.5 px-2 rounded-lg bg-slate-50">
                      <svg className="w-3.5 h-3.5 text-slate-400 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>
                      <span className="text-xs text-slate-600">{c.title}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}
            {/* Related Decisions */}
            {relatedDecisions.length > 0 && (
              <div>
                <h4 className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-1.5">Related Decisions</h4>
                <div className="space-y-1">
                  {relatedDecisions.map(d => (
                    <div key={d.id} className="flex items-center gap-2 py-1.5 px-2 rounded-lg bg-slate-50">
                      <svg className="w-3.5 h-3.5 text-slate-400 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7h12m0 0l-4-4m4 4l-4 4m0 6H4m0 0l4 4m-4-4l4-4" /></svg>
                      <span className="text-xs text-slate-600">{d.title}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}
            {/* Best For / Not Ideal For */}
            <div className="grid grid-cols-1 gap-3">
              {insight.bestFor && insight.bestFor.length > 0 && (
                <div>
                  <h4 className="text-xs font-semibold text-emerald-600 uppercase tracking-wider mb-1.5">Best for</h4>
                  <ul className="space-y-1">{insight.bestFor.map((item, i) => (
                    <li key={i} className="flex items-start gap-2 text-xs text-slate-600"><span className="text-emerald-500 mt-0.5 shrink-0">✓</span><span>{item}</span></li>
                  ))}</ul>
                </div>
              )}
              {insight.notIdealFor && insight.notIdealFor.length > 0 && (
                <div>
                  <h4 className="text-xs font-semibold text-amber-600 uppercase tracking-wider mb-1.5">Not ideal for</h4>
                  <ul className="space-y-1">{insight.notIdealFor.map((item, i) => (
                    <li key={i} className="flex items-start gap-2 text-xs text-slate-600"><span className="text-amber-500 mt-0.5 shrink-0">✗</span><span>{item}</span></li>
                  ))}</ul>
                </div>
              )}
            </div>
          </div>
        </section>

        {/* Engagement — Like */}
        <section className="bg-white rounded-xl border border-slate-200 overflow-hidden">
          <div className="p-4 flex items-center gap-4">
            <button onClick={handleLike} className={`flex items-center gap-2 px-4 py-2 rounded-lg border transition-colors ${liked ? 'bg-red-50 border-red-200 text-red-600' : 'bg-white border-slate-200 text-slate-500 hover:bg-slate-50'}`}>
              <svg className={`w-4 h-4 ${liked ? 'fill-red-500 text-red-500' : ''}`} fill={liked ? 'currentColor' : 'none'} stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" /></svg>
              <span className="text-sm font-medium tabular-nums">{localLikeCount}</span>
            </button>
            <span className="text-xs text-slate-400">{liked ? 'You liked this' : 'Like this insight'}</span>
          </div>
        </section>

        {/* Comments */}
        <section className="bg-white rounded-xl border border-slate-200 overflow-hidden">
          <div className="px-4 py-3 border-b border-slate-200 bg-slate-50"><h3 className="text-sm font-medium text-slate-700">Comments ({localComments.length})</h3></div>
          <div className="p-4 space-y-3">
            {localComments.length === 0 && <p className="text-sm text-slate-400 text-center py-3">No comments yet.</p>}
            {localComments.map(cm => (
              <div key={cm.id} className="flex items-start gap-2.5">
                <div className="w-7 h-7 rounded-full bg-slate-200 flex items-center justify-center shrink-0"><span className="text-[10px] font-bold text-slate-500">{cm.author.charAt(0)}</span></div>
                <div className="flex-1 min-w-0"><div className="flex items-baseline gap-2"><span className="text-xs font-semibold text-slate-700">{cm.author}</span><span className="text-[10px] text-slate-400">{cm.time}</span></div><p className="text-sm text-slate-600 mt-0.5">{cm.text}</p></div>
              </div>
            ))}
            <div className="flex gap-2 pt-2 border-t border-slate-100">
              <input type="text" value={commentText} onChange={e => setCommentText(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleAddComment()} placeholder="Add a comment..." className="flex-1 text-sm border border-slate-200 rounded-lg px-3 py-2 focus:outline-none focus:border-blue-400 focus:ring-1 focus:ring-blue-100" />
              <button onClick={handleAddComment} disabled={!commentText.trim()} className="px-3 py-2 text-sm font-medium text-white bg-slate-800 rounded-lg hover:bg-slate-700 transition-colors disabled:opacity-40 disabled:cursor-not-allowed">Post</button>
            </div>
          </div>
        </section>
      </main>
      <div className="h-20" />
    </div>
  );
};

// ============================================
// COMPONENT: Publisher Profile Page
// ============================================
const PublisherProfilePage = ({ publisherId, onBack, onSelectInsight }) => {
  // Find all insights by this author
  const authorInsights = insightsData.filter(i => i.author && i.author.id === publisherId);
  const author = authorInsights.length > 0 ? authorInsights[0].author : null;

  const perspectiveColors = {
    Homeowner: 'bg-emerald-100 text-emerald-700',
    GC: 'bg-orange-100 text-orange-700',
    Designer: 'bg-purple-100 text-purple-700',
    Vendor: 'bg-sky-100 text-sky-700',
    Agent: 'bg-rose-100 text-rose-700',
  };

  const roleBgColors = {
    Homeowner: 'bg-emerald-50 border-emerald-200',
    GC: 'bg-orange-50 border-orange-200',
    Designer: 'bg-purple-50 border-purple-200',
    Vendor: 'bg-sky-50 border-sky-200',
    Agent: 'bg-rose-50 border-rose-200',
  };

  if (!author) return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center">
      <div className="text-center"><p className="text-slate-500 text-sm">Publisher not found</p><button onClick={onBack} className="mt-3 text-blue-600 text-sm font-medium">Go back</button></div>
    </div>
  );

  // Sort author insights by publishedAt desc
  const sorted = [...authorInsights].sort((a, b) => new Date(b.publishedAt) - new Date(a.publishedAt));
  const totalLikes = authorInsights.reduce((s, i) => s + i.likeCount, 0);

  return (
    <div className="min-h-screen bg-slate-50">
      <header className="bg-white border-b border-slate-200 px-4 py-3 sticky top-0 z-10">
        <div className="max-w-lg mx-auto flex items-center gap-3">
          <button onClick={onBack} className="p-1 -ml-1 hover:bg-slate-100 rounded-lg transition-colors shrink-0">
            <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
          </button>
          <div className="flex-1 min-w-0">
            <h1 className="text-base font-semibold text-slate-800 truncate">Publisher</h1>
          </div>
        </div>
      </header>

      <main className="max-w-lg mx-auto px-4 py-4 space-y-4">
        {/* Author Header Card */}
        <section className={`rounded-xl border overflow-hidden ${roleBgColors[author.roleLabel] || 'bg-slate-50 border-slate-200'}`}>
          <div className="p-5 flex items-center gap-4">
            <div className="w-14 h-14 rounded-full bg-white border-2 border-white shadow-sm flex items-center justify-center shrink-0">
              <span className="text-base font-bold text-slate-500">{author.avatarInitials}</span>
            </div>
            <div className="flex-1 min-w-0">
              <h2 className="text-lg font-semibold text-slate-800">{author.name}</h2>
              <span className={`inline-block mt-1 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wider rounded-full ${perspectiveColors[author.roleLabel] || 'bg-slate-100 text-slate-600'}`}>{author.roleLabel}</span>
              <div className="flex items-center gap-4 mt-2">
                <span className="text-xs text-slate-500">{authorInsights.length} insight{authorInsights.length !== 1 ? 's' : ''}</span>
                <span className="text-xs text-slate-500">{totalLikes} helpful vote{totalLikes !== 1 ? 's' : ''}</span>
              </div>
            </div>
          </div>
        </section>

        {/* Published Insights */}
        <section>
          <h3 className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-2.5">Published Insights</h3>
          <div className="grid grid-cols-1 gap-3">
            {sorted.map(insight => (
              <button key={insight.id} onClick={() => onSelectInsight(insight.id)} className="w-full text-left bg-white rounded-xl border border-slate-200 p-4 hover:border-slate-300 hover:shadow-sm transition-all group">
                <div className="flex items-start gap-2 mb-2 flex-wrap">
                  <span className={`inline-block px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wider rounded-full ${perspectiveColors[insight.perspective] || 'bg-slate-100 text-slate-600'}`}>{insight.perspective}</span>
                  {insight.contextTags.map(tag => (
                    <span key={tag} className="inline-block px-2 py-0.5 text-[10px] font-medium text-slate-500 bg-slate-100 rounded-full">{tag}</span>
                  ))}
                </div>
                <h3 className="text-sm font-semibold text-slate-800 leading-snug group-hover:text-blue-700 transition-colors">{insight.title}</h3>
                <p className="text-xs text-slate-500 mt-1.5 line-clamp-2 leading-relaxed">{insight.summary}</p>
                {insight.publishedAt && (
                  <p className="text-[11px] text-slate-400 mt-2">{new Date(insight.publishedAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}</p>
                )}
                <div className="flex items-center gap-4 mt-3 pt-2.5 border-t border-slate-100">
                  <div className="flex items-center gap-1.5">
                    <svg className="w-3.5 h-3.5 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" /></svg>
                    <span className="text-xs text-slate-500 tabular-nums">{insight.likeCount}</span>
                  </div>
                  <div className="flex items-center gap-1.5">
                    <svg className="w-3.5 h-3.5 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z" /></svg>
                    <span className="text-xs text-slate-500 tabular-nums">{insight.commentCount}</span>
                  </div>
                </div>
              </button>
            ))}
          </div>
        </section>
      </main>
      <div className="h-20" />
    </div>
  );
};

