// ============================================
// VENDOR IMAGE STORE (safeStorage persistence for base64 images)
// ============================================
const VENDOR_IMG_KEY = 'vendorImageStore';
const VENDOR_PRODUCTS_KEY = 'vendorProductsStore';
const VENDOR_CASES_KEY = 'vendorCasesStore';

const vendorImageStore = {
  _read() { try { return JSON.parse(safeStorage.getItem(VENDOR_IMG_KEY)) || {}; } catch { return {}; } },
  _write(data) { safeStorage.setItem(VENDOR_IMG_KEY, JSON.stringify(data)); },
  saveImage(img) { const d = this._read(); d[img.id] = img; this._write(d); return img; },
  getImage(id) { return this._read()[id] || null; },
  getImages(ids) { const d = this._read(); return ids.map(id => d[id]).filter(Boolean); },
  deleteImage(id) { const d = this._read(); delete d[id]; this._write(d); },
  deleteImages(ids) { const d = this._read(); ids.forEach(id => delete d[id]); this._write(d); },
};

const vendorDataStore = {
  loadProducts() { try { const s = safeStorage.getItem(VENDOR_PRODUCTS_KEY); return s ? JSON.parse(s) : null; } catch { return null; } },
  saveProducts(products) { safeStorage.setItem(VENDOR_PRODUCTS_KEY, JSON.stringify(products)); },
  loadCases() { try { const s = safeStorage.getItem(VENDOR_CASES_KEY); return s ? JSON.parse(s) : null; } catch { return null; } },
  saveCases(cases) { safeStorage.setItem(VENDOR_CASES_KEY, JSON.stringify(cases)); },
};

// Helper: read files as base64 and create ImageAsset objects
const readFilesAsImages = (files) => {
  return Promise.all(Array.from(files).map(file => new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve({ id: 'img-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8), dataUrl: reader.result, filename: file.name, mimeType: file.type, createdAt: Date.now() });
    reader.onerror = reject;
    reader.readAsDataURL(file);
  })));
};

// Helper: get cover image URL from images array
const getCoverUrl = (images) => {
  if (!images || images.length === 0) return '';
  const first = images[0];
  if (first.dataUrl) return first.dataUrl;
  const stored = vendorImageStore.getImage(first.id);
  return stored?.dataUrl || '';
};

// Helper: get image data URL (from memory or store)
const getImageUrl = (img) => {
  if (!img) return '';
  if (img.dataUrl) return img.dataUrl;
  const stored = vendorImageStore.getImage(img.id);
  return stored?.dataUrl || '';
};

// Helper: migrate old product/case data to new images format
const migrateProductImages = (product) => {
  if (product.images) return product;
  return { ...product, images: [], imageUrl: undefined };
};

const migrateCaseToContentBlocks = (c) => {
  if (c.contentBlocks) return c;
  const blocks = [];
  const sections = ['description', 'constraints', 'delivered', 'outcome'];
  sections.forEach(s => {
    if (c[s]) blocks.push({ type: 'text', section: s, text: c[s] });
  });
  return { ...c, images: c.images || [], contentBlocks: blocks, imageUrl: undefined };
};

// ============================================
// SHARED: Image Upload Control
// ============================================
const ImageUploadControl = ({ images, onChange, label }) => {
  const fileRef = React.useRef(null);
  const handleFiles = async (e) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;
    const newImgs = await readFilesAsImages(files);
    newImgs.forEach(img => vendorImageStore.saveImage(img));
    onChange([...images, ...newImgs]);
    if (fileRef.current) fileRef.current.value = '';
  };
  const removeImage = (id) => {
    vendorImageStore.deleteImage(id);
    onChange(images.filter(i => i.id !== id));
  };
  const moveImage = (idx, dir) => {
    const arr = [...images];
    const newIdx = idx + dir;
    if (newIdx < 0 || newIdx >= arr.length) return;
    [arr[idx], arr[newIdx]] = [arr[newIdx], arr[idx]];
    onChange(arr);
  };
  return (
    <div>
      <label className="text-[10px] font-semibold text-slate-500 uppercase tracking-wider">{label || 'Images'}</label>
      <div className="mt-1.5">
        {images.length > 0 && (
          <div className="grid grid-cols-3 gap-2 mb-2">
            {images.map((img, idx) => (
              <div key={img.id} className="relative group rounded-lg overflow-hidden border border-slate-200 aspect-square bg-slate-100">
                <img src={getImageUrl(img)} alt={img.filename || ''} className="w-full h-full object-cover" />
                {idx === 0 && <span className="absolute top-1 left-1 text-[8px] font-bold text-white bg-black/50 px-1.5 py-0.5 rounded-full backdrop-blur-sm">Cover</span>}
                <div className="absolute inset-0 bg-black/0 group-hover:bg-black/30 transition-all flex items-center justify-center gap-1 opacity-0 group-hover:opacity-100">
                  {idx > 0 && <button onClick={() => moveImage(idx, -1)} className="w-6 h-6 bg-white/90 rounded-full flex items-center justify-center text-slate-600 hover:bg-white"><svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg></button>}
                  {idx < images.length - 1 && <button onClick={() => moveImage(idx, 1)} className="w-6 h-6 bg-white/90 rounded-full flex items-center justify-center text-slate-600 hover:bg-white"><svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg></button>}
                  <button onClick={() => removeImage(img.id)} className="w-6 h-6 bg-red-500/90 rounded-full flex items-center justify-center text-white hover:bg-red-600"><svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg></button>
                </div>
              </div>
            ))}
          </div>
        )}
        <button onClick={() => fileRef.current?.click()} className="w-full py-3 border-2 border-dashed border-slate-300 rounded-xl text-xs font-medium text-slate-500 hover:border-sky-400 hover:text-sky-600 hover:bg-sky-50 transition-all flex items-center justify-center gap-2">
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
          {images.length > 0 ? 'Add More Photos' : 'Upload Photos'}
        </button>
        <input ref={fileRef} type="file" accept="image/*" multiple onChange={handleFiles} className="hidden" />
      </div>
    </div>
  );
};

// ============================================
// SHARED: Image Viewer (main + thumbnail strip)
// ============================================
const ImageViewer = ({ images, emptyMessage, onAddPhotos }) => {
  const [activeIdx, setActiveIdx] = React.useState(0);
  if (!images || images.length === 0) {
    return (
      <div className="bg-slate-100 rounded-xl border border-slate-200 p-6 text-center">
        <svg className="w-10 h-10 mx-auto text-slate-300 mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
        <p className="text-xs text-slate-400">{emptyMessage || 'No photos yet'}</p>
        {onAddPhotos && <button onClick={onAddPhotos} className="mt-2 text-xs font-semibold text-sky-600 hover:text-sky-700">+ Add Photos</button>}
      </div>
    );
  }
  const safeIdx = Math.min(activeIdx, images.length - 1);
  return (
    <div className="rounded-xl overflow-hidden border border-slate-200 bg-white">
      <div className="relative w-full aspect-[4/3] bg-slate-100">
        <img src={getImageUrl(images[safeIdx])} alt={images[safeIdx]?.filename || 'Photo'} className="w-full h-full object-cover" />
        <span className="absolute bottom-2 right-2 text-[10px] font-medium text-white bg-black/50 backdrop-blur-sm px-2 py-0.5 rounded-full">{safeIdx + 1} / {images.length}</span>
      </div>
      {images.length > 1 && (
        <div className="p-2 flex gap-1.5 overflow-x-auto">
          {images.map((img, idx) => (
            <button key={img.id} onClick={() => setActiveIdx(idx)} className={`w-14 h-14 rounded-lg overflow-hidden shrink-0 border-2 transition-all ${idx === safeIdx ? 'border-sky-500 ring-1 ring-sky-200' : 'border-transparent opacity-70 hover:opacity-100'}`}>
              <img src={getImageUrl(img)} alt="" className="w-full h-full object-cover" />
            </button>
          ))}
        </div>
      )}
    </div>
  );
};

